-- grok made ts
local function IK2Bone(from: Vector3, target: Vector3, direction: Vector3, lenA: number, lenB: number): CFrame
-- 2-segment IK solver (upper arm lenA, forearm lenB). Returns CFrame at target position
-- whose rotation orients the bone next to the hand (forearm) using the pole direction
-- for the elbow bend plane. Logic tested: elbow solved via law-of-cosines + pole projection;
-- last bone roll is pole-consistent so the entire chain stays in the correct plane.
-- Handles full extension when unreachable; assumes reachable for under-extension (standard).
local root = from
local goal = target
local pole = direction
local toGoal = goal - root
local dist = toGoal.Magnitude
if dist < 1e-6 then
return CFrame.new(goal) -- degenerate case, no valid plane
end
local dir = toGoal / dist
-- project pole onto plane perpendicular to dir (defines bend direction)
local poleProj = pole - dir * pole:Dot(dir)
local poleMag = poleProj.Magnitude
if poleMag < 1e-6 then
-- fallback perpendicular (avoids singularity)
local arb = Vector3.yAxis
if math.abs(dir:Dot(arb)) > 0.99 then
arb = Vector3.xAxis
end
poleProj = (arb - dir * arb:Dot(dir)).Unit
else
poleProj /= poleMag
end
-- compute elbow position
local elbowPos
if dist > lenA + lenB then
-- fully extended toward target (unreachable case)
elbowPos = root + dir * lenA
else
-- standard triangle solution
local a = (lenA * lenA + dist * dist - lenB * lenB) / (2 * dist)
local hSq = lenA * lenA - a * a
local h = hSq > 0 and math.sqrt(hSq) or 0
elbowPos = root + dir * a + poleProj * h
end
-- forearm direction (bone next to hand)
local boneDir = (goal - elbowPos).Unit
-- project pole onto plane perpendicular to forearm for consistent roll/up
local desiredUp = pole - boneDir * pole:Dot(boneDir)
local upMag = desiredUp.Magnitude
if upMag < 1e-6 then
local arb = Vector3.yAxis
if math.abs(boneDir:Dot(arb)) > 0.99 then
arb = Vector3.xAxis
end
desiredUp = (arb - boneDir * arb:Dot(boneDir)).Unit
else
desiredUp /= upMag
end
-- CFrame at target with LookVector along bone (forward = boneDir from elbow → hand)
-- and UpVector pole-projected so rotation respects "elbow points" direction
return CFrame.lookAt(goal, goal + boneDir, desiredUp)
end

-- ===== movement (matched to the original Clover VR script) =====
-- walk 8 / sprint 28 (tweened), crouch = elastic drop, jump power 50, point-walk (Y), point-teleport (B / C),
-- foot planting that only re-steps when a foot gets too far from where it should be. body is still built from the
-- normal R6 parts, no hats.
local WALK_SPEED = 8
local SPRINT_SPEED = 22 -- sprint (was 28, a bit too fast)
local SPRINT_TWEEN = 0.5 -- seconds, Sine Out (was 1)
local JUMP_POWER = 50

local CROUCH_DISTANCE = 1.5 -- studs your view drops (original: StudsOffset - 1.5)
local CROUCH_TWEEN = 1 -- seconds, Elastic Out (same as the original)

local POINTER_RANGE = 1000 -- how far the pointer beam reaches
local TELEPORT_RANGE = 1000 -- original only teleports if the target is closer than this

local NO_COLLISION_PLAYERS = true -- other players don't push you around (same as the original NoCollision)
local NO_COLLISION_RANGE = 30

-- foot placement (original FootReady / FootYield / UpdateFooting numbers)
local FOOT_MAX_DIST_MOVING = 0.5 -- re-step when a foot is this far from where it should be (moving)
local FOOT_MAX_DIST_IDLE = 1 -- ...and this far when standing still
local FOOT_REFRESH_TIME = 2 -- feet re-settle every 2 seconds regardless
local FOOT_YIELD_TIME = 0.15 -- gap between the right foot and left foot stepping
local FOOT_LEAD_DIV = 4.2 -- feet reach ahead by WalkSpeed / 4.2 while moving
local FOOT_MAX_LEAD = 1.2 -- R6 legs are shorter than R15, so the reach is capped (studs)
local FOOT_STEP_TIME = 0.2 -- how long a foot takes to swing to its new spot
local FOOT_STEP_HEIGHT = 0.1 -- foot lift while swinging (fraction of the step length)
local FOOT_SPREAD = 1.25 -- feet stand a little wider than the hips so the legs don't look stuck together while walking

-- sprinting: instead of planting feet (which turns into huge stretched strides at high speed) the legs swing in a fixed
-- walk-sized cycle, so a sprint looks like a faster walk and not a stride
local GAIT_START = 11 -- speed (studs/s) where the swing cycle starts blending in (walk is 8)
local GAIT_RAMP = 5 -- ...and it's fully on this much faster
local GAIT_FREQ = 2.9 -- steps per second per leg
local GAIT_STRIDE = 1.1 -- how far each foot swings forward/back (studs)
local GAIT_LIFT = 0.5 -- how high the foot lifts on the forward swing (studs)

-- jumping: the legs tuck up into the torso, one after the other (no kick)
local AIR_DEBOUNCE = 0.05 -- seconds of real freefall/jump before the legs react (stops flicker on bumps and slopes)
local TUCK_DELAY = 0.12 -- the second leg tucks this much later than the first
local TUCK_SPEED = 14 -- how quickly a leg slides in / back out (higher = snappier)

local LegsTarget = {}
local FakeVRArms = {}
local Crouching = false
local CrouchDistance = 0
local TorsoRotation = CFrame.identity
local Sprinting = false

local conns = {}
local FootState = {Turn = 2, Clock = 0, Debounce = 0, Air = false, AirTime = 0, Phase = 0}

local function DisconnectAll()
for _, c in conns do
c:Disconnect()
end
table.clear(conns)
end

-- ---------- crouch (hold L2 / LeftCtrl) ----------
local crouchValue = Instance.new("NumberValue")
local crouchTween

local function SetCrouch(on)
if Crouching == on then return end
Crouching = on
if crouchTween then crouchTween:Cancel() end
crouchTween = TweenService:Create(crouchValue, TweenInfo.new(CROUCH_TWEEN, Enum.EasingStyle.Elastic, Enum.EasingDirection.Out), {Value = on and CROUCH_DISTANCE or 0})
crouchTween:Play()
end

-- ---------- sprint (hold R2 / LeftShift) ----------
local sprintTween

local function SetSprint(on)
Sprinting = on
if not hum then return end
if sprintTween then sprintTween:Cancel() end
sprintTween = TweenService:Create(hum, TweenInfo.new(SPRINT_TWEEN, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {WalkSpeed = on and SPRINT_SPEED or WALK_SPEED})
sprintTween:Play()
end

-- ---------- pointer beam (point-walk with Y, point-teleport with B / C) ----------
local Pointer = {Enabled = false, Walk = false, Teleport = false, Hit = false, Position = Vector3.zero, Distance = 0}
local pointerFolder, pointerHand, pointerTarget, pointerBeam, pointerParticles

local function PointerMakePart(name)
local p = Instance.new("Part")
p.Name = name
p.Anchored = true
p.CanCollide = false
p.CanQuery = false
p.CanTouch = false
p.CastShadow = false
p.Transparency = 1
p.Size = Vector3.new(0.1, 0.1, 0.1)
p.Parent = pointerFolder
return p
end

local function PointerDestroy()
if pointerFolder then pointerFolder:Destroy() end
pointerFolder, pointerHand, pointerTarget, pointerBeam, pointerParticles = nil, nil, nil, nil, nil
Pointer.Enabled, Pointer.Walk, Pointer.Teleport, Pointer.Hit = false, false, false, false
end

local function PointerCreate()
PointerDestroy()
pointerFolder = Instance.new("Folder")
pointerFolder.Name = "ClovrPointer"
pointerFolder.Parent = workspace

pointerHand = PointerMakePart("Hand")
pointerTarget = PointerMakePart("Target")
pointerTarget.Shape = Enum.PartType.Cylinder -- flat disc that lies on whatever you point at
pointerTarget.Size = Vector3.new(0.1, 1.6, 1.6)
pointerTarget.Material = Enum.Material.Neon
pointerTarget.Color = Color3.fromRGB(90, 180, 255)

local a0 = Instance.new("Attachment")
a0.Parent = pointerHand
local a1 = Instance.new("Attachment")
a1.Parent = pointerTarget

pointerBeam = Instance.new("Beam")
pointerBeam.Attachment0 = a0
pointerBeam.Attachment1 = a1
pointerBeam.Width0 = 0.05
pointerBeam.Width1 = 0.05
pointerBeam.FaceCamera = true
pointerBeam.LightEmission = 1
pointerBeam.Segments = 1
pointerBeam.Color = ColorSequence.new(Color3.fromRGB(90, 180, 255))
pointerBeam.Transparency = NumberSequence.new(0.3)
pointerBeam.Enabled = false
pointerBeam.Parent = pointerHand

pointerParticles = Instance.new("ParticleEmitter")
pointerParticles.EmissionDirection = Enum.NormalId.Right -- the disc's flat side faces along its X axis
pointerParticles.Rate = 20
pointerParticles.Lifetime = NumberRange.new(0.5, 1)
pointerParticles.Speed = NumberRange.new(1, 3)
pointerParticles.SpreadAngle = Vector2.new(25, 25)
pointerParticles.Size = NumberSequence.new(0.25, 0)
pointerParticles.LightEmission = 1
pointerParticles.Color = ColorSequence.new(Color3.fromRGB(90, 180, 255))
pointerParticles.Enabled = false
pointerParticles.Parent = pointerTarget
end

-- kind = "Walk" (Y) or "Teleport" (B / C)
local function PointerSet(kind, on)
Pointer[kind] = on
local enabled = Pointer.Walk or Pointer.Teleport
Pointer.Enabled = enabled
if not enabled then Pointer.Hit = false end
if pointerBeam then pointerBeam.Enabled = enabled end
if pointerParticles then pointerParticles.Enabled = enabled end
if pointerTarget then pointerTarget.Transparency = enabled and 0.35 or 1 end
end

-- rayOrigin/rayDir decide WHAT you point at (VR: your right hand, flat screen: your cursor), handPos is where the beam starts
local function PointerUpdate(rayOrigin: Vector3, rayDir: Vector3, handPos: Vector3)
if not (Pointer.Enabled and pointerHand and pointerTarget) then return end
local hit = PhysicsRaycast(rayOrigin, rayDir * POINTER_RANGE)
local pos = hit and hit.Position or rayOrigin + rayDir * POINTER_RANGE
Pointer.Hit = hit ~= nil
Pointer.Position = pos
Pointer.Distance = (pos - rayOrigin).Magnitude
pointerHand.CFrame = CFrame.new(handPos)
local normal = hit and hit.Normal or -rayDir
local up = math.abs(normal.Y) > 0.99 and Vector3.xAxis or Vector3.yAxis
pointerTarget.CFrame = CFrame.lookAt(pos, pos + normal, up) * CFrame.Angles(0, math.rad(90), 0)
end

-- original: VirtualBody:MoveTo + VirtualRig:SetPrimaryPartCFrame + both feet snapped to the new spot
local function TeleportTo(pos: Vector3)
if not (hum and root) then return end
local legPart = root.Parent and root.Parent:FindFirstChild("Left Leg")
local legHeight = legPart and legPart.Size.Y or 2 * scale
local height = hum.HipHeight + legHeight + root.Size.Y / 2
local cf = CFrame.new(pos + Vector3.new(0, height + 0.25, 0)) * root.CFrame.Rotation
SetCFrame(root, cf)
root.AssemblyLinearVelocity = Vector3.zero
local base = CFrame.new(pos) * cf.Rotation
for _, leg in LegsTarget do
local p = base * Vector3.new(leg.Side * scale, 0, 0)
leg.Pos, leg.From, leg.Goal, leg.T = p, p, p, 1
end
FootState.Debounce = os.clock()
end

-- ---------- feet ----------
local function MakeLeg(side, tuckDelay)
local pos = root.CFrame * Vector3.new(side, -3, 0)
return {
Side = side * FOOT_SPREAD, -- where the foot stands (a bit wider than the hip)
Offset = Vector3.new(side, -1, 0), -- hip joint on the torso
Pos = pos, -- where the foot is right now
From = pos, -- where the current step started
Goal = pos, -- where the current step ends (the planted spot)
T = 1, -- step progress, 1 = planted
Tuck = 0, -- 0 = normal, 1 = fully tucked into the torso
TuckDelay = tuckDelay or 0,
Realism = {Vector3.zero, Vector3.zero, Vector3.zero, Vector3.zero},
}
end

local function GetLegPoint(leg)
return leg.Pos
end

-- where this foot should be standing: under the hip, to its side, with a lead in the direction you're moving.
-- the lead is based on WALK speed, so sprinting doesn't make the stride any bigger
local function GetFootTarget(leg, hip: Vector3, flat: CFrame, moveDir: Vector3)
if hum:GetState() == Enum.HumanoidStateType.Climbing then
local origin = torso.CFrame * (leg.Offset * scale) + Vector3.new(0, -0.5, 0) * scale
local look = root.CFrame.LookVector * 3 * scale
local hit = PhysicsRaycast(origin, look)
return hit and hit.Position or origin + Vector3.new(0, -2, 0) * scale
end
local floor = PhysicsRaycast(hip, Vector3.new(0, -3 * scale, 0))
local dist = floor and floor.Distance or 3 * scale
dist = math.clamp(dist, 0, 5 * scale)
local side = (flat * CFrame.new(leg.Side * scale, 0, 0)).Position
local lead = math.min(WALK_SPEED / FOOT_LEAD_DIV, FOOT_MAX_LEAD) * scale
return Vector3.new(side.X, hip.Y - dist, side.Z) + moveDir * lead
end

-- the original's early-out: step right away if a foot got way out of reach
local function FootBreak(hip: Vector3)
local reach = math.min(WALK_SPEED / 2.5, 2.2) * scale
for _, leg in LegsTarget do
if math.abs(hip.Y - leg.Goal.Y) > 4 * scale then return true end
if ((torso.Position - leg.Goal) * Vector3.new(1, 0, 1)).Magnitude > reach then return true end
end
return false
end

-- right foot, short wait, left foot, short wait, ... (original UpdateFooting loop)
local function StepFeet(dt)
local state = hum:GetState()
local jumping = state == Enum.HumanoidStateType.Jumping or state == Enum.HumanoidStateType.Freefall
if jumping then
FootState.AirTime += dt
else
FootState.AirTime = 0
end
local wasAir = FootState.Air
FootState.Air = FootState.AirTime > AIR_DEBOUNCE
FootState.Phase += dt * GAIT_FREQ * math.pi * 2

if FootState.Air then return end
if wasAir then
FootState.Clock = 0 -- just landed: plant a foot straight away
end

local now = os.clock()
local hip = torso.CFrame * Vector3.new(0, -1 * scale, 0)
if now - FootState.Clock < FOOT_YIELD_TIME and not FootBreak(hip) then return end
FootState.Clock = now

local leg = LegsTarget[FootState.Turn]
FootState.Turn = FootState.Turn % 2 + 1

local md = hum.MoveDirection
local moveDir = Vector3.new(md.X, 0, md.Z)
local look = root.CFrame.LookVector * Vector3.new(1, 0, 1)
if look.Magnitude < 1e-3 then look = Vector3.zAxis end
local flat = CFrame.lookAt(hip, hip + look)

local target = GetFootTarget(leg, hip, flat, moveDir)
local maxDist = (moveDir.Magnitude > 0 and FOOT_MAX_DIST_MOVING or FOOT_MAX_DIST_IDLE) * scale
if (leg.Pos - target).Magnitude > maxDist or now - FootState.Debounce >= FOOT_REFRESH_TIME then
FootState.Debounce = now
leg.From, leg.Goal, leg.T = leg.Pos, target, 0
end
end

local function ProcessLegs(leg, dt)
local last
for _=1, 1 do
last = Vector3.new(math.random() * 2 - 1, math.random() * 2 - 1, math.random() * 2 - 1) * 0.2
for i=1, #leg.Realism do
last = last:Lerp(leg.Realism[i], math.exp(-16 * dt))
leg.Realism[i] = last
end
end
local real = CFrame.Angles(last.X, last.Y, last.Z)

local tgt
if FootState.Air then
-- jumping / falling: the foot just hangs under the hip (it gets tucked into the torso below)
tgt = torso.CFrame * Vector3.new(leg.Side * scale, -2.9 * scale, 0)
leg.Pos, leg.From, leg.Goal, leg.T = tgt, tgt, tgt, 1
leg.Blend = 0
else
leg.T = math.min(1, leg.T + dt / FOOT_STEP_TIME)
local eased = 1 - (1 - leg.T) ^ 2
leg.Pos = leg.From:Lerp(leg.Goal, eased)
tgt = leg.Pos + Vector3.new(0, math.sin(math.pi * leg.T) * (leg.Goal - leg.From).Magnitude * FOOT_STEP_HEIGHT, 0)

-- sprinting: blend into a fixed-size swing cycle so it looks like a faster walk, not a stride
local vel = root.Velocity * Vector3.new(1, 0, 1)
local rawBlend = math.clamp((vel.Magnitude - GAIT_START) / GAIT_RAMP, 0, 1)
leg.Blend = (leg.Blend or 0) + (rawBlend - (leg.Blend or 0)) * (1 - math.exp(-10 * dt)) -- smoothed so the legs don't flicker between walk and run
local blend = leg.Blend
if blend > 0.001 and hum:GetState() ~= Enum.HumanoidStateType.Climbing then
local hip = torso.CFrame * Vector3.new(0, -1 * scale, 0)
local floor = PhysicsRaycast(hip, Vector3.new(0, -3 * scale, 0))
local dist = math.clamp(floor and floor.Distance or 3 * scale, 0, 5 * scale)
local fwd = vel.Magnitude > 0.5 and vel.Unit or (root.CFrame.LookVector * Vector3.new(1, 0, 1)).Unit
local base = (CFrame.lookAt(hip, hip + fwd) * CFrame.new(leg.Side * scale, 0, 0)).Position
local ph = FootState.Phase + (leg.Side > 0 and 0 or math.pi)
local gait = Vector3.new(base.X, hip.Y - dist, base.Z)
+ fwd * (math.sin(ph) * GAIT_STRIDE * scale)
+ Vector3.new(0, math.max(0, math.cos(ph)) * GAIT_LIFT * scale, 0)
tgt = tgt:Lerp(gait, blend)
end
end

local orig = torso.CFrame * (leg.Offset * scale)
local dir = root.CFrame.Rotation * Vector3.new(leg.Offset.X, 0, -2)
local pose
if (tgt - orig).Magnitude > 2.1 * scale then
tgt = orig + (tgt - orig).Unit * 2.1 * scale
pose = CFrame.lookAlong(tgt, tgt - orig, dir) * real * CFrame.Angles(1.57, 0, 0) * CFrame.new(0, 1 * scale, 0)
else
pose = IK2Bone(orig, tgt, dir, 0.7 * scale, 1.2 * scale) * real * CFrame.Angles(1.57, 0, 0) * CFrame.new(0, 1 * scale, 0)
end

-- jump tuck: the leg slides straight up into the torso (same spot, same angle as the torso), first leg right away,
-- second leg a moment later. no kick, it just eases in and eases back out on landing
local wantTuck = (FootState.Air and FootState.AirTime >= AIR_DEBOUNCE + leg.TuckDelay) and 1 or 0
leg.Tuck += (wantTuck - leg.Tuck) * (1 - math.exp(-TUCK_SPEED * dt))
if leg.Tuck > 0.002 then
local inside = torso.CFrame * CFrame.new(leg.Offset.X * scale, 0, 0)
pose = pose:Lerp(inside, math.min(leg.Tuck, 1))
end
return pose
end

local function ProcessArms(arm, dt, vro, headcf)
local last
for _=1, 1 do
last = Vector3.new(math.random() * 2 - 1, math.random() * 2 - 1, math.random() * 2 - 1) * 0.5
for i=1, #arm.Realism do
last = last:Lerp(arm.Realism[i], math.exp(-16 * dt))
arm.Realism[i] = last
end
end
local cast = PhysicsRaycast(vro.Position, headcf.LookVector * 32 * scale)
if cast then
cast = (cast.Position - vro.Position - arm.Offset.Position).Unit
if cast ~= cast or cast.Magnitude == 0 then
cast = headcf.LookVector
end
else
cast = headcf.LookVector
end
local ha = CFrame.new(0, -0.5, 0) * CFrame.Angles(0.3 + last.X, last.Y, last.Z) * CFrame.new(0, -0.4, 0) * CFrame.Angles(-1.57, 0, 0)
local hb = CFrame.lookAlong(Vector3.zero, cast) * CFrame.new(0, 0, -0.5) * CFrame.Angles(last.X, last.Y, last.Z) * CFrame.new(0, 0, -0.5)
local tm = arm.Timer
if arm.Waving then
tm = math.min(1, tm + dt / 0.2)
else
tm = math.max(0, tm - dt / 0.2)
end
arm.Timer = tm
return arm.Offset * ha:Lerp(hb, TweenService:GetValue(tm, Enum.EasingStyle.Cubic, Enum.EasingDirection.InOut))
end
-- ===== characters-only viewport (bottom right) =====
-- shows ONLY your body + other players. no map, no world.
local ContentProvider = cloneref(game:GetService("ContentProvider"))
local VIEWPORT_SCALE = 0.3 -- box is 30% of your screen width/height (same as the original script)
local VIEWPORT_RANGE = 80 -- studs: other players within this show up
local VIEWPORT_MAX_OTHERS = 10 -- closest N other players get drawn
-- camera angle copied from the original script: sits 5 studs to the side and 2 up from your head, looking at your head
local VIEWPORT_CAM_OFFSET = Vector3.new(5, 2, 0)
local vpGui, vpFrame, vpCam, vpConn, vpFigure, vpViewPart
-- [model] = {clone = Model, drivers = {{driverPart, offset, clonePart}, ...}, want = Model, sig = n}
local vpTracked = {}
local vpScanTimer = 0
-- strips non-visual stuff from a clone (scripts would run inside PlayerGui, joints fight the CFrame sync)
local function VPStrip(inst)
for _, v in inst:GetDescendants() do
if v:IsA("Humanoid") then
v.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
v.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
elseif v:IsA("BaseScript") or v:IsA("JointInstance") or v:IsA("WeldConstraint") or v:IsA("Constraint") or v:IsA("Sound") or v:IsA("BodyMover") or v:IsA("BillboardGui") or v:IsA("SurfaceGui") then
v:Destroy()
end
end
end
local function VPUntrack(model)
local info = vpTracked[model]
if info then
info.clone:Destroy()
vpTracked[model] = nil
end
end
local function VPGetParts(model)
local list = {}
for _, v in model:GetDescendants() do
if v:IsA("BasePart") then table.insert(list, v) end
end
return list
end
-- changes whenever clothing / accessories / packages get added or removed
local function VPSignature(model)
return #model:GetDescendants()
end
-- full clone with EVERYTHING kept (packages, clothing, accessories, face). temporarily forces
-- Archivable on so nothing gets silently dropped
local function VPFullClone(model)
local changed = {}
if not model.Archivable then
model.Archivable = true
table.insert(changed, model)
end
for _, v in model:GetDescendants() do
if not v.Archivable then
v.Archivable = true
table.insert(changed, v)
end
end
local ok, clone = pcall(function() return model:Clone() end)
for _, v in changed do
pcall(function() v.Archivable = false end)
end
return ok and clone or nil
end
-- which model to copy the LOOKS from (your real avatar for your own dummy)
local function VPSourceFor(model)
if model == vpFigure then
local real = Player.Character
if real and real.Parent and real ~= model and real:FindFirstChildOfClass("Humanoid") and real:FindFirstChild("Torso") then
return real
end
end
return model
end
local function VPTrack(model)
if vpTracked[model] or not vpFrame then return end
local isSelf = model == vpFigure
local want = VPSourceFor(model)
local src = want
local clone = VPFullClone(src)
if not clone and src ~= model then
src = model
clone = VPFullClone(src)
end
if not clone then return end
local drivers = {}
if src == model then
-- looks + movement both come from this model: pair parts one-to-one
local origParts, cloneParts = VPGetParts(model), VPGetParts(clone)
if #origParts ~= #cloneParts or #origParts == 0 then
clone:Destroy()
return
end
for i, o in origParts do
drivers[i] = {o, CFrame.identity, cloneParts[i]}
end
else
-- looks come from your real avatar, movement comes from your reanimated body (matched by part name);
-- accessories ride along using their weld offsets
local figure = model
local resolved = {}
local joints = {} -- [part] = list of joints touching it (accessory welds AND tool grips)
for _, j in clone:GetDescendants() do
if j:IsA("JointInstance") then
if j.Part0 then
joints[j.Part0] = joints[j.Part0] or {}
table.insert(joints[j.Part0], j)
end
if j.Part1 then
joints[j.Part1] = joints[j.Part1] or {}
table.insert(joints[j.Part1], j)
end
end
end
local function resolve(p)
local r = resolved[p]
if r ~= nil then return r end
resolved[p] = false
local direct = p.Parent == clone and figure:FindFirstChild(p.Name)
if direct and direct:IsA("BasePart") then
r = {direct, CFrame.identity}
else
for _, j in joints[p] or {} do
if j:IsA("JointInstance") then
local other, off
if j.Part0 == p and j.Part1 then
other, off = j.Part1, j.C1 * j.C0:Inverse()
elseif j.Part1 == p and j.Part0 then
other, off = j.Part0, j.C0 * j.C1:Inverse()
end
if other then
local base = resolve(other)
if base then
r = {base[1], base[2] * off}
break
end
end
end
end
end
resolved[p] = r or false
return resolved[p]
end
for _, p in VPGetParts(clone) do
local r = resolve(p)
if r then
table.insert(drivers, {r[1], r[2], p})
else
p:Destroy()
end
end
end
for _, d in drivers do
local c = d[3]
c.Anchored = true
c.CanCollide = false
c.CanQuery = false
c.CanTouch = false
c.LocalTransparencyModifier = 0
if c.Name == "HumanoidRootPart" then
c.Transparency = 1
elseif isSelf then
c.Transparency = 0 -- the body-transparency slider never shows on your viewport dummy
end
end
VPStrip(clone)
clone.Parent = vpFrame
vpTracked[model] = {clone = clone, drivers = drivers, want = want, sig = VPSignature(want)}
-- make sure meshes/textures finish loading so nothing stays a plain block
task.spawn(function()
pcall(function() ContentProvider:PreloadAsync(clone:GetDescendants()) end)
end)
end
local function VPDestroy()
if vpConn then vpConn:Disconnect() vpConn = nil end
for model in vpTracked do VPUntrack(model) end
if vpGui then vpGui:Destroy() end
if vpViewPart then vpViewPart:Destroy() end
vpGui, vpFrame, vpCam, vpFigure, vpViewPart = nil, nil, nil, nil, nil
end
local function VPUpdate(dt)
local figure = vpFigure
if not (vpFrame and figure and figure.Parent) then return end
local root = figure:FindFirstChild("HumanoidRootPart") or figure:FindFirstChild("Torso") or figure.PrimaryPart
if not root then return end
local focus = root.Position
-- every half second: add/remove/refresh characters
vpScanTimer += dt
if vpScanTimer > 0.5 then
vpScanTimer = 0
local wanted = {[figure] = true} -- YOUR body is always shown
local near = {}
for _, plr in Players:GetPlayers() do
local char = plr ~= Player and plr.Character
if char then
local r = char:FindFirstChild("HumanoidRootPart")
if r then
local dist = (r.Position - focus).Magnitude
if dist <= VIEWPORT_RANGE then
table.insert(near, {char, dist})
end
end
end
end
table.sort(near, function(a, b) return a[2] < b[2] end)
for i = 1, math.min(#near, VIEWPORT_MAX_OTHERS) do
wanted[near[i][1]] = true
end
for model in wanted do
local info = vpTracked[model]
if info then
local want = VPSourceFor(model)
if info.want ~= want or VPSignature(want) ~= info.sig then
VPUntrack(model) -- respawned or outfit changed: rebuild
end
end
VPTrack(model)
end
for model in vpTracked do
if not wanted[model] then VPUntrack(model) end
end
end
-- mirror the real movement onto the clones
for model, info in vpTracked do
if not model.Parent then
VPUntrack(model)
else
for _, d in info.drivers do
if d[1].Parent then d[3].CFrame = d[1].CFrame * d[2] end
end
end
end
-- camera (copied from the original script): fixed side angle, aimed at your head
local render
if VRService.VREnabled then
local cam = workspace.CurrentCamera
local renderCF = cam.CFrame * VRService:GetUserCFrame(Enum.UserCFrame.Head)
render = renderCF.Position
-- VR: the box lives on a billboard 16 studs in front of your head, same as the original
if vpViewPart and vpGui then
vpViewPart.CFrame = renderCF * CFrame.new(0, 0, -16)
local size = cam.ViewportSize
vpGui.Size = UDim2.new(0, size.X - 6, 0, size.Y - 6)
end
else
local head = figure:FindFirstChild("Head")
render = head and head.Position or focus
end
vpCam.CFrame = CFrame.new(render + VIEWPORT_CAM_OFFSET, render)
end
local function VPCreate(figure)
VPDestroy()
vpFigure = figure
local guiParent = (gethui and gethui()) or Player:FindFirstChildOfClass("PlayerGui")
vpFrame = Instance.new("ViewportFrame")
vpFrame.Size = UDim2.new(VIEWPORT_SCALE, 0, VIEWPORT_SCALE, 0)
if VRService.VREnabled then
-- VR: billboard in front of your head, box placed exactly like the original script
vpViewPart = Instance.new("Part")
vpViewPart.Name = "ClovrViewPart"
vpViewPart.Anchored = true
vpViewPart.CanCollide = false
vpViewPart.CanQuery = false
vpViewPart.CanTouch = false
vpViewPart.Transparency = 1
vpViewPart.Size = Vector3.new(0.05, 0.05, 0.05)
vpViewPart.Parent = workspace.CurrentCamera
vpGui = Instance.new("BillboardGui")
vpGui.Name = "ClovrViewport"
vpGui.Adornee = vpViewPart
vpGui.AlwaysOnTop = true
vpGui.LightInfluence = 0
vpGui.Size = UDim2.new(0, 800, 0, 600)
vpGui.Parent = guiParent
vpFrame.AnchorPoint = Vector2.new(0.5, 1)
vpFrame.Position = UDim2.new(0.62, 0, 0.89, 0)
else
-- flat screen: bottom right corner
vpGui = Instance.new("ScreenGui")
vpGui.Name = "ClovrViewport"
vpGui.ResetOnSpawn = false
vpGui.IgnoreGuiInset = true
vpGui.DisplayOrder = 10
vpGui.Parent = guiParent
vpFrame.AnchorPoint = Vector2.new(1, 1)
vpFrame.Position = UDim2.new(0.99, 0, 0.99, 0)
end
vpFrame.BackgroundTransparency = 1 -- transparent box
vpFrame.BorderSizePixel = 0
vpFrame.Ambient = Color3.fromRGB(190, 190, 190)
vpFrame.LightColor = Color3.fromRGB(255, 255, 255)
vpFrame.Parent = vpGui
vpCam = Instance.new("Camera")
vpCam.FieldOfView = 70
vpCam.Parent = vpFrame
vpFrame.CurrentCamera = vpCam
vpConn = RunService.RenderStepped:Connect(VPUpdate)
end
-- ===== end viewport =====
-- ===== chat HUD (modern TextChatService, plus a topic overview tab) =====
-- Sits on the INNER (palm) side of your left hand, like a wrist display. It only shows while that
-- inner side is turned toward your eyes; turn your hand away and it disappears.
-- Tabs: All / Overview (what each person is talking about).
-- Toggle on/off: tap L2 on controller (or H on keyboard). Switch tab: X on controller or J on keyboard.
local CHAT_OVERVIEW_WINDOW = 180 -- seconds of chat the Overview tab looks at
local CHAT_MAX_STORED = 150
local CHAT_MAX_SHOWN = 40
local CHAT_TABS = {"All", "Overview"}
local CHAT_PANEL_SIZE = Vector3.new(2.0, 1.3, 0.05) -- studs (keep the same ratio as the 480x312 canvas)
local CHAT_PALM_OFFSET = 0.9 -- studs the panel floats off the inner side of your hand
local CHAT_FACE_SHOW = 0.45 -- shows once your palm faces you this much (1 = straight at you)
local CHAT_FACE_HIDE = 0.25 -- hides again when it turns away past this
local chGui, chMain, chList, chConns, chTabButtons, chToken, chPart
local chShown, chFacing = true, false
local chUpIndex = 1
local chMessages = {}
local chSeen = {}
local chTab = 1
local chStop = {}
for w in ("the and for you that this with have are was but not just its it's i'm dont don't what your from they them then than there their about would could should like get got can cant can't will one out all any has had how who why when where yes yeah okay too very really also into over some more only now here let lets let's him her his she hes she's did does doing been being were our off want need see say said going gonna wanna"):gmatch("%S+") do
chStop[w] = true
end
local function CHEscape(s)
s = s:gsub("&", "&amp;")
s = s:gsub("<", "&lt;")
s = s:gsub(">", "&gt;")
s = s:gsub('"', "&quot;")
s = s:gsub("'", "&apos;")
return s
end
local function CHMyPosition()
local root = vpFigure and vpFigure:FindFirstChild("HumanoidRootPart")
if root then return root.Position end
local cam = workspace.CurrentCamera
return cam and cam.CFrame.Position
end
local function CHDistanceTo(plr)
if plr == Player then return 0 end
local char = plr and plr.Character
local part = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head"))
local me = CHMyPosition()
if part and me then
return math.floor((part.Position - me).Magnitude + 0.5)
end
return nil
end
-- most common meaningful words in a list of messages
local function CHKeywords(texts, n)
local counts = {}
for _, t in texts do
for w in t:lower():gmatch("[%a']+") do
if #w >= 3 and not chStop[w] then
counts[w] = (counts[w] or 0) + 1
end
end
end
local arr = {}
for w, c in counts do
table.insert(arr, {w, c})
end
table.sort(arr, function(a, b)
if a[2] ~= b[2] then return a[2] > b[2] end
return a[1] < b[1]
end)
local out = {}
for i = 1, math.min(n, #arr) do
out[i] = arr[i][1]
end
return out
end
local function CHNameColor(userId)
return Color3.fromHSV((userId % 360) / 360, 0.55, 1):ToHex()
end
local function CHFormat(m)
local tag = m.dist and ("(" .. m.dist .. ") ") or ""
return ('<font color="#%s"><b>%s%s:</b></font> %s'):format(CHNameColor(m.userId), tag, CHEscape(m.name), CHEscape(m.text))
end
local function CHClearList()
for _, c in chList:GetChildren() do
if c:IsA("GuiObject") then c:Destroy() end
end
end
local function CHAddLabel(text, order)
local l = Instance.new("TextLabel")
l.BackgroundTransparency = 1
l.Size = UDim2.new(1, -8, 0, 0)
l.AutomaticSize = Enum.AutomaticSize.Y
l.TextWrapped = true
l.RichText = true
l.TextXAlignment = Enum.TextXAlignment.Left
l.TextYAlignment = Enum.TextYAlignment.Top
l.Font = Enum.Font.SourceSans
l.TextSize = 24
l.TextColor3 = Color3.new(1, 1, 1)
l.TextStrokeTransparency = 0.7
l.LayoutOrder = order
l.Text = text
l.Parent = chList
end
-- simple local summary (keyword based, not AI): who is talking about what in the last few minutes
local function CHRenderOverview()
local now = os.time()
local recent, byPlayer, people = {}, {}, {}
for _, m in chMessages do
if now - m.time <= CHAT_OVERVIEW_WINDOW then
table.insert(recent, m)
local e = byPlayer[m.userId]
if not e then
e = {name = m.name, userId = m.userId, texts = {}, last = m, count = 0, asks = 0}
byPlayer[m.userId] = e
table.insert(people, e)
end
table.insert(e.texts, m.text)
e.last = m
e.count += 1
if m.text:find("?", 1, true) then e.asks += 1 end
end
end
local minutes = math.floor(CHAT_OVERVIEW_WINDOW / 60)
if #recent == 0 then
CHAddLabel(("<i>Nothing said in the last %d min.</i>"):format(minutes), 1)
return
end
local order = 1
CHAddLabel(("<b>Chat overview</b> (last %d min, %d messages)"):format(minutes, #recent), order)
local all = {}
for _, m in recent do table.insert(all, m.text) end
local topics = CHKeywords(all, 5)
order += 1
if #topics > 0 then
CHAddLabel("Main topics: <b>" .. CHEscape(table.concat(topics, ", ")) .. "</b>", order)
else
CHAddLabel("<i>Mostly short chatter.</i>", order)
end
table.sort(people, function(a, b) return a.last.time > b.last.time end)
for _, e in people do
local kws = CHKeywords(e.texts, 3)
local about = #kws > 0 and table.concat(kws, ", ") or "short chatter"
local snippet = e.last.text
local len = utf8.len(snippet)
if len and len > 60 then
snippet = snippet:sub(1, (utf8.offset(snippet, 58) or 58) - 1) .. "..."
end
local extra = e.asks > 0 and " · asking questions" or ""
order += 1
CHAddLabel(('<font color="#%s"><b>%s</b></font>: about <b>%s</b> · %d msg%s\n<i>"%s"</i>'):format(
CHNameColor(e.userId), CHEscape(e.name), CHEscape(about), e.count, (e.count == 1 and "" or "s") .. extra, CHEscape(snippet)), order)
end
end
local function CHRender()
if not chList then return end
CHClearList()
if chTab == 2 then
CHRenderOverview()
chList.CanvasPosition = Vector2.new(0, 0)
return
end
local shown = {}
for i = #chMessages, 1, -1 do
table.insert(shown, 1, chMessages[i])
if #shown >= CHAT_MAX_SHOWN then break end
end
for i, m in shown do
CHAddLabel(CHFormat(m), i)
end
-- stay scrolled to the newest message
task.defer(function()
if chList then
chList.CanvasPosition = Vector2.new(0, chList.AbsoluteCanvasSize.Y)
end
end)
end
local function CHUpdateTabs()
if not chTabButtons then return end
for i, b in chTabButtons do
local on = i == chTab
b.BackgroundColor3 = on and Color3.fromRGB(60, 120, 255) or Color3.fromRGB(35, 35, 35)
b.Font = on and Enum.Font.SourceSansBold or Enum.Font.SourceSans
end
end
local function CHSetTab(i)
chTab = i
CHUpdateTabs()
CHRender()
end
local function CHAddMessage(plr, name, userId, text)
if not chList or text == "" then return end
table.insert(chMessages, {time = os.time(), userId = userId, name = name, text = text, dist = CHDistanceTo(plr)})
if #chMessages > CHAT_MAX_STORED then
table.remove(chMessages, 1)
end
CHRender()
end
local function CHDestroy()
chToken = nil
if chConns then
for _, c in chConns do c:Disconnect() end
end
chConns = nil
if chGui then chGui:Destroy() end
if chPart then chPart:Destroy() end
chGui, chMain, chList, chTabButtons, chPart = nil, nil, nil, nil, nil
chFacing = false
table.clear(chMessages)
table.clear(chSeen)
end
local function CHToggle()
chShown = not chShown
if chGui then chGui.Enabled = chShown and chFacing end
end
-- keeps the panel on the inner side of your left hand and hides it unless that side faces you
local function CHUpdate()
if not (chPart and chGui) then return end
local cam = workspace.CurrentCamera
local camCF = (ReanimCamera and ReanimCamera.CFrame) or (cam and cam.CFrame)
if not camCF then return end
local handPos, normal, fingers
local arm = vpFigure and vpFigure:FindFirstChild("Left Arm")
if arm then
local cf = arm.CFrame
normal = cf.RightVector -- inner side of the left arm/hand
fingers = -cf.UpVector -- toward your fingers
handPos = cf.Position + fingers * 0.4
elseif VRService.VREnabled and cam then
local cf = cam.CFrame * VRService:GetUserCFrame(Enum.UserCFrame.LeftHand)
normal = cf.RightVector
fingers = cf.LookVector
handPos = cf.Position
else
chGui.Enabled = false
return
end
local pos = handPos + normal * CHAT_PALM_OFFSET
local toEyes = camCF.Position - pos
local facing = toEyes.Magnitude > 1e-3 and normal:Dot(toEyes.Unit) or -1
if chFacing then
if facing < CHAT_FACE_HIDE then chFacing = false end
elseif facing > CHAT_FACE_SHOW then
chFacing = true
end
-- keep the text horizontal: use whichever panel "up" (along or across your hand) is closest to world up
local candidates = {fingers, -fingers, normal:Cross(fingers), -normal:Cross(fingers)}
local up = candidates[chUpIndex]
local upDot = up:Dot(Vector3.yAxis)
for i, c in candidates do
local d = c:Dot(Vector3.yAxis)
if d > upDot + 0.15 then
chUpIndex, up, upDot = i, c, d
end
end
chPart.CFrame = CFrame.lookAt(pos, pos + normal, up)
chGui.Enabled = chShown and chFacing
end
local function CHCreate()
CHDestroy()
local token = {}
chToken = token
chConns = {}
chTab = 1
chShown, chFacing = true, false
chPart = Instance.new("Part")
chPart.Name = "ClovrChatPart"
chPart.Anchored = true
chPart.CanCollide = false
chPart.CanQuery = false
chPart.CanTouch = false
chPart.CastShadow = false
chPart.Transparency = 1
chPart.Size = CHAT_PANEL_SIZE
chPart.Parent = workspace
chGui = Instance.new("SurfaceGui")
chGui.Name = "ClovrChat"
chGui.Adornee = chPart
chGui.Face = Enum.NormalId.Front
chGui.Enabled = false
chGui.AlwaysOnTop = true
chGui.LightInfluence = 0
chGui.ResetOnSpawn = false
chGui.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
chGui.CanvasSize = Vector2.new(480, 312)
chGui.Parent = (gethui and gethui()) or Player:FindFirstChildOfClass("PlayerGui")
chMain = Instance.new("Frame")
chMain.Name = "Chat"
chMain.Size = UDim2.new(1, 0, 1, 0)
chMain.BackgroundColor3 = Color3.new(0, 0, 0)
chMain.BackgroundTransparency = 0.55
chMain.BorderSizePixel = 0
chMain.Parent = chGui
local corner = Instance.new("UICorner")
corner.CornerRadius = UDim.new(0, 8)
corner.Parent = chMain
local bar = Instance.new("Frame")
bar.BackgroundTransparency = 1
bar.Size = UDim2.new(1, 0, 0, 34)
bar.Parent = chMain
local barLayout = Instance.new("UIListLayout")
barLayout.FillDirection = Enum.FillDirection.Horizontal
barLayout.SortOrder = Enum.SortOrder.LayoutOrder
barLayout.Parent = bar
chTabButtons = {}
for i, name in CHAT_TABS do
local b = Instance.new("TextButton")
b.LayoutOrder = i
b.Size = UDim2.new(1 / #CHAT_TABS, 0, 1, 0)
b.Text = name
b.TextSize = 24
b.TextColor3 = Color3.new(1, 1, 1)
b.BorderSizePixel = 0
b.AutoButtonColor = false
b.Parent = bar
chTabButtons[i] = b
table.insert(chConns, b.Activated:Connect(function() CHSetTab(i) end))
end
chList = Instance.new("ScrollingFrame")
chList.Position = UDim2.new(0, 0, 0, 34)
chList.Size = UDim2.new(1, 0, 1, -34)
chList.BackgroundTransparency = 1
chList.BorderSizePixel = 0
chList.ScrollBarThickness = 4
chList.CanvasSize = UDim2.new()
chList.AutomaticCanvasSize = Enum.AutomaticSize.Y
chList.Parent = chMain
local listLayout = Instance.new("UIListLayout")
listLayout.SortOrder = Enum.SortOrder.LayoutOrder
listLayout.Padding = UDim.new(0, 3)
listLayout.Parent = chList
local pad = Instance.new("UIPadding")
pad.PaddingLeft, pad.PaddingRight, pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 6), UDim.new(0, 6), UDim.new(0, 4), UDim.new(0, 4)
pad.Parent = chList
-- where messages come from: the current Roblox chat (TextChatService), or the old chat as a fallback
local modern = false
pcall(function()
modern = TextChatService.ChatVersion == Enum.ChatVersion.TextChatService
end)
if modern then
table.insert(chConns, TextChatService.MessageReceived:Connect(function(msg)
local src = msg.TextSource
if not src then return end -- system messages
if msg.MessageId ~= "" then
if chSeen[msg.MessageId] then return end
chSeen[msg.MessageId] = true
end
local plr = Players:GetPlayerByUserId(src.UserId)
CHAddMessage(plr, plr and plr.DisplayName or src.Name, src.UserId, msg.Text)
end))
else
local function hook(plr)
table.insert(chConns, plr.Chatted:Connect(function(text)
CHAddMessage(plr, plr.DisplayName, plr.UserId, text)
end))
end
for _, plr in Players:GetPlayers() do hook(plr) end
table.insert(chConns, Players.PlayerAdded:Connect(hook))
end
-- H = show/hide the box (L2 tap does it too), X / J = next tab
table.insert(chConns, UserInputService.InputBegan:Connect(function(input, processed)
local key = input.KeyCode
local typing = processed or UserInputService:GetFocusedTextBox() ~= nil
if key == Enum.KeyCode.H and not typing then
CHToggle()
elseif key == Enum.KeyCode.ButtonX or (key == Enum.KeyCode.J and not typing) then
CHSetTab(chTab % #CHAT_TABS + 1)
end
end))
-- follow the left hand every frame
table.insert(chConns, RunService.RenderStepped:Connect(CHUpdate))
-- keep the overview fresh as old messages age out
task.spawn(function()
while chToken == token do
task.wait(5)
if chToken == token and chTab == 2 then CHRender() end
end
end)
CHSetTab(1)
end
-- ===== end chat HUD =====

m.Init = function(figure: Model)

arewelikestillbeingused = true
curFigure = figure
m.handpos = S.HandPos
m.Transparency = S.Transparency
pcall(function() StarterGui:SetCore("VREnableControllerModels", false) end) -- hide the default VR controller models
ApplyTransparency()

spawn(function()
while arewelikestillbeingused do
task.wait(0.4)
ApplyTransparency()
end
end)

hum = figure:FindFirstChild("Humanoid")
root = figure:FindFirstChild("HumanoidRootPart")
torso = figure:FindFirstChild("Torso")
if not hum then return end
if not root then return end
if not torso then return end

DisconnectAll() -- in case the moveset gets re-initialized

hum.WalkSpeed = WALK_SPEED
hum.UseJumpPower = true
hum.JumpPower = JUMP_POWER

VPCreate(figure)
CHCreate()
PointerCreate()

--ReanimCamera.FPSLocked = true

for _,v in figure:GetChildren() do
if v:IsA("BasePart") then
for _,w in figure:GetChildren() do
if v ~= w and w:IsA("BasePart") then
local nocoll = Instance.new("NoCollisionConstraint", v)
nocoll.Part0, nocoll.Part1 = v, w
end
end
end
end

LegsTarget = {MakeLeg(-0.5, 0), MakeLeg(0.5, TUCK_DELAY)} -- [1] = left (tucks first), [2] = right (tucks a moment later)

FakeVRArms = {
{
Timer = 1,
Realism = {Vector3.zero, Vector3.zero, Vector3.zero, Vector3.zero},
Waving = false,
Offset = CFrame.new(-1.5, -1, 0),
},
{
Timer = 1,
Realism = {Vector3.zero, Vector3.zero, Vector3.zero, Vector3.zero},
Waving = false,
Offset = CFrame.new(1.5, -1, 0),
},
}

Crouching = false
CrouchDistance = 0
crouchValue.Value = 0
Sprinting = false
FootState.Turn, FootState.Clock, FootState.Debounce, FootState.Air, FootState.AirTime = 2, 0, os.clock(), false, 0

-- jump (original: JumpRequest -> jump)
table.insert(conns, UserInputService.JumpRequest:Connect(function()
if hum and hum.Parent then hum.Jump = true end
end))

-- point-walk (hold Y) + no collision with nearby players
table.insert(conns, RunService.Stepped:Connect(function()
if not (hum and hum.Parent and root and root.Parent) then return end

if Pointer.Walk and Pointer.Hit then
local flatDist = ((Pointer.Position - root.Position) * Vector3.new(1, 0, 1)).Magnitude
if flatDist > 1.5 then
hum:MoveTo(Pointer.Position)
end
end

if NO_COLLISION_PLAYERS then
for _, plr in Players:GetPlayers() do
local char = plr ~= Player and plr.Character
if char then
local base = char.PrimaryPart or char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
if base and (base.Position - root.Position).Magnitude < NO_COLLISION_RANGE then
for _, part in char:GetChildren() do
if part:IsA("BasePart") then part.CanCollide = false end
end
end
end
end
end
end))

-- ===== controls =====
-- L2 / LCtrl = crouch (hold)     L2 tap = chat on/off
-- R2 / LShift = sprint (hold)
-- Y = point-walk (hold)          B / C = point-teleport (hold to aim, let go to go)
-- X / J = chat tab               H = chat on/off
-- flat screen: left click / right click = point left / right arm

ContextActions:BindAction("Uhhhhhh_VRWaveL", function(_, state, _)
if state == Enum.UserInputState.Begin then
FakeVRArms[1].Waving = true
end
if state == Enum.UserInputState.End then
FakeVRArms[1].Waving = false
end
end, true, Enum.UserInputType.MouseButton1)
ContextActions:SetTitle("Uhhhhhh_VRWaveL", "L")
ContextActions:SetPosition("Uhhhhhh_VRWaveL", UDim2.new(1, -230, 1, -130))

ContextActions:BindAction("Uhhhhhh_VRWaveR", function(_, state, _)
if state == Enum.UserInputState.Begin then
FakeVRArms[2].Waving = true
end
if state == Enum.UserInputState.End then
FakeVRArms[2].Waving = false
end
end, true, Enum.UserInputType.MouseButton2)
ContextActions:SetTitle("Uhhhhhh_VRWaveR", "R")
ContextActions:SetPosition("Uhhhhhh_VRWaveR", UDim2.new(1, -180, 1, -130))

local l2DownTime = 0
ContextActions:BindAction("Uhhhhhh_VRCrouch", function(_, state, input)
local isL2 = input and input.KeyCode == Enum.KeyCode.ButtonL2
if state == Enum.UserInputState.Begin then
if isL2 then l2DownTime = os.clock() end
SetCrouch(true)
elseif state == Enum.UserInputState.End or state == Enum.UserInputState.Cancel then
SetCrouch(false)
if isL2 and state == Enum.UserInputState.End and os.clock() - l2DownTime < 0.25 then
CHToggle()
end
end
return Enum.ContextActionResult.Pass
end, true, Enum.KeyCode.LeftControl, Enum.KeyCode.ButtonL2)
ContextActions:SetTitle("Uhhhhhh_VRCrouch", "Crouch")
ContextActions:SetPosition("Uhhhhhh_VRCrouch", UDim2.new(1, -130, 1, -230))

ContextActions:BindAction("Uhhhhhh_VRRun", function(_, state, _)
if state == Enum.UserInputState.Begin then
SetSprint(true)
elseif state == Enum.UserInputState.End or state == Enum.UserInputState.Cancel then
SetSprint(false)
end
return Enum.ContextActionResult.Pass
end, true, Enum.KeyCode.LeftShift, Enum.KeyCode.ButtonR2)
ContextActions:SetTitle("Uhhhhhh_VRRun", "Run")
ContextActions:SetPosition("Uhhhhhh_VRRun", UDim2.new(1, -180, 1, -230))

ContextActions:BindAction("Uhhhhhh_VRTeleport", function(_, state, _)
if state == Enum.UserInputState.Begin then
PointerSet("Teleport", true)
elseif state == Enum.UserInputState.End or state == Enum.UserInputState.Cancel then
if state == Enum.UserInputState.End and Pointer.Teleport and Pointer.Hit and Pointer.Distance < TELEPORT_RANGE then
TeleportTo(Pointer.Position)
end
PointerSet("Teleport", false)
end
return Enum.ContextActionResult.Pass
end, true, Enum.KeyCode.C, Enum.KeyCode.ButtonB)
ContextActions:SetTitle("Uhhhhhh_VRTeleport", "TP")
ContextActions:SetPosition("Uhhhhhh_VRTeleport", UDim2.new(1, -230, 1, -230))

ContextActions:BindAction("Uhhhhhh_VRPointWalk", function(_, state, _)
if state == Enum.UserInputState.Begin then
PointerSet("Walk", true)
elseif state == Enum.UserInputState.End or state == Enum.UserInputState.Cancel then
PointerSet("Walk", false)
if hum and root and hum.Parent then
hum:MoveTo(root.Position) -- stop where you are
end
end
return Enum.ContextActionResult.Pass
end, false, Enum.KeyCode.ButtonY)

end

m.Update = function(dt: number, figure: Model)

local t = os.clock()
scale = figure:GetScale()
isdancing = not not figure:GetAttribute("IsDancing")

local filter = {figure}
if Player.Character then table.insert(filter, Player.Character) end
if pointerFolder then table.insert(filter, pointerFolder) end
rcp.FilterDescendantsInstances = filter

-- get vii
hum = figure:FindFirstChild("Humanoid")
root = figure:FindFirstChild("HumanoidRootPart")
torso = figure:FindFirstChild("Torso")
if not hum then return end
if not root then return end
if not torso then return end

-- joints
local rj = root:FindFirstChild("RootJoint")
local nj = torso:FindFirstChild("Neck")
local rsj = torso:FindFirstChild("Right Shoulder")
local lsj = torso:FindFirstChild("Left Shoulder")
local rhj = torso:FindFirstChild("Right Hip")
local lhj = torso:FindFirstChild("Left Hip")

-- crouch amount comes from the elastic tween (see SetCrouch)
CrouchDistance = crouchValue.Value

if not isdancing then

rj.Enabled, nj.Enabled, rsj.Enabled, lsj.Enabled, rhj.Enabled, lhj.Enabled = false, false, false, false, false, false
--hum.HipHeight = 2 * scale
hum.HipHeight = 2 * scale - 2 - CrouchDistance * scale
root.CustomPhysicalProperties = PhysicalProperties.new(3.15, 0.3, 0.5)

local head = figure:FindFirstChild("Head")
local rarm = figure:FindFirstChild("Right Arm")
local larm = figure:FindFirstChild("Left Arm")
local rleg = figure:FindFirstChild("Right Leg")
local lleg = figure:FindFirstChild("Left Leg")
local chead, clarm, crarm

local vro = root.CFrame * CFrame.new(0, 1.5 * scale, 0)
local vroot = root.CFrame
vro += Vector3.new(0, CrouchDistance * scale, 0)
vroot += Vector3.new(0, CrouchDistance * scale, 0)

if VRService.VREnabled then
chead, clarm, crarm = VRService:GetUserCFrame(Enum.UserCFrame.Head), VRService:GetUserCFrame(Enum.UserCFrame.LeftHand), VRService:GetUserCFrame(Enum.UserCFrame.RightHand)
if ReanimCamera:IsFirstPerson() then
local _, y, _ = chead:ToEulerAngles(Enum.RotationOrder.YXZ)
vro *= CFrame.Angles(0, -y, 0)
end
else
local x, y, z = root.CFrame.Rotation:ToObjectSpace(ReanimCamera.CFrame.Rotation):ToEulerAngles(Enum.RotationOrder.YXZ)
if ReanimCamera:IsFirstPerson() then
y *= 0
else
if math.abs(y) > math.pi / 2 then
y = math.pi - y
end
end
chead = CFrame.new(0, -0.5, 0) * CFrame.fromEulerAngles(x, y, z, Enum.RotationOrder.YXZ) * CFrame.new(0, 0.5, 0) + Vector3.new(0, -CrouchDistance, 0)
clarm = ProcessArms(FakeVRArms[1], dt, vro, chead) + Vector3.new(0, -CrouchDistance, 0)
crarm = ProcessArms(FakeVRArms[2], dt, vro, chead) + Vector3.new(0, -CrouchDistance, 0)
end

chead += chead.Position * (scale - 1)
clarm += clarm.Position * (scale - 1)
crarm += crarm.Position * (scale - 1)

-- pointer beam (Y = walk to it, B / C = teleport to it)
if Pointer.Enabled then
local handWorld = vro * crarm
if VRService.VREnabled then
-- VR: you point with your right hand
PointerUpdate(handWorld.Position, handWorld.LookVector, handWorld.Position)
else
-- flat screen: you point with your cursor, the beam leaves your right hand
local ray = mouse.UnitRay
PointerUpdate(ray.Origin, ray.Direction, handWorld.Position)
end
end

local armo = CFrame.Angles(1.57, 0, 0) * CFrame.new(0, m.handpos, 0)
SetCFrame(head, vro * chead)
SetCFrame(larm, vro * clarm * armo)
SetCFrame(rarm, vro * crarm * armo)

local z1, z2 = vroot:PointToObjectSpace(GetLegPoint(LegsTarget[1])).Z, vroot:PointToObjectSpace(GetLegPoint(LegsTarget[2])).Z
local yabai = CFrame.Angles(0, math.atan(z1 - z2) * 0.5 / scale, 0)
TorsoRotation = yabai:Lerp(TorsoRotation, math.exp(-4 * dt))
SetCFrame(torso, IK2Bone(
vroot * Vector3.new(0, -3 * scale, 0),
vro * chead * Vector3.new(0, -0.5 * scale, 0),
-vroot.LookVector, 1.5 * scale, 1.5 * scale) * CFrame.Angles(1.57, 3.14, 3.14) * CFrame.new(0, -1 * scale, 0) * TorsoRotation)

StepFeet(dt) -- decides when each foot re-plants (needs the torso where it is this frame)
SetCFrame(lleg, ProcessLegs(LegsTarget[1], dt))
SetCFrame(rleg, ProcessLegs(LegsTarget[2], dt))

else

rj.Enabled, nj.Enabled, rsj.Enabled, lsj.Enabled, rhj.Enabled, lhj.Enabled = true, true, true, true, true, true
hum.HipHeight = 2 * scale - 2
root.CustomPhysicalProperties = nil

end

end

m.Destroy = function(figure: Model?)

arewelikestillbeingused = false
pcall(function() StarterGui:SetCore("VREnableControllerModels", true) end) -- give the controller models back

DisconnectAll()
if crouchTween then crouchTween:Cancel() end
if sprintTween then sprintTween:Cancel() end
crouchValue.Value = 0
Crouching, Sprinting = false, false

PointerDestroy()
VPDestroy()
CHDestroy()

ContextActions:UnbindAction("Uhhhhhh_VRWaveL")
ContextActions:UnbindAction("Uhhhhhh_VRWaveR")
ContextActions:UnbindAction("Uhhhhhh_VRCrouch")
ContextActions:UnbindAction("Uhhhhhh_VRRun")
ContextActions:UnbindAction("Uhhhhhh_VRTeleport")
ContextActions:UnbindAction("Uhhhhhh_VRPointWalk")

end

return m

end)

return modules

end)
if not ok then
    (warn or print)("[KernelPacker] failed to load clovr_module_v2.lua: " .. tostring(result))
elseif type(result) == "table" and result ~= modules then
    for _, fn in ipairs(result) do table.insert(modules, fn) end
end
end

return modules
